<?php namespace App\Policies; use App\Models\Central\TenantMembership; use App\Models\Tenant\Company;use App\Models\User;use App\Tenancy\TenantContext; class CompanyPolicy {public function view(User $user,Company $company):bool{return $this->member($user);}public function create(User $user):bool{return $this->member($user);}public function update(User $user,Company $company):bool{return $this->member($user);} private function member(User $user):bool{$tenant=app(TenantContext::class)->tenant();return TenantMembership::query()->where('tenant_id',$tenant->id)->where('user_id',$user->id)->where('status','active')->exists();}}
